void triangle(int n) {
    for (int i = 1; i <= n; i++) {      // rows
        for (int j = 1; j <= i; j++)     // stars in row i
            cout << "* ";
        cout << "\n";
    }
}

void pyramid(int n) {
    for (int i = 1; i <= n; i++) {
        for (int s = 0; s < n - i; s++) cout << " ";   // leading spaces
        for (int j = 0; j < 2*i - 1; j++) cout << "*"; // 2i-1 stars
        cout << "\n";
    }
}
